function solution(works) {
    const count = {};

    works.forEach(work => {
        const workType = Math.floor(work / 10000); // 첫째 자리
        const employee = work % 10000; // 나머지 (직원번호)

        if (workType === 5) {
            count[employee] = (count[employee] || 0) + 1;
        }
    });

    // 최대값과 최소 직원번호 찾기
    let maxCount = 0;
    let resultEmployee = Infinity;

    for (let emp in count) {
        if (count[emp] > maxCount ||
           (count[emp] === maxCount && Number(emp) < resultEmployee)) {
            maxCount = count[emp];
            resultEmployee = Number(emp);
        }
    }

    return resultEmployee;
}

