function solution(target, strings) {
    const words = target.toLowerCase().split(' ');
    const pattern1 = words.join(' ');   // "nile river"
    const pattern2 = words.join('');    // "nileriver"

    const result = [];

    for (let i = 0; i < strings.length; i++) {
        const normalized = strings[i].toLowerCase();

        if (normalized === pattern1 || normalized === pattern2) {
            result.push(1);
        } else {
            result.push(0);
        }
    }

    return result;
}

