function solution(binaryStrings) {
    const hashMap = {}; // '[2,1,3]': [1, 3] 형태로 저장

    // 각 이진 문자열 처리
    for (let i = 0; i < binaryStrings.length; i++) {
        const binary = binaryStrings[i];
        const lengths = [];
        let count = 0;

        // 연속된 1의 길이 구하기
        for (let j = 0; j < binary.length; j++) {
            if (binary[j] === '1') {
                count++;
            } else {
                if (count > 0) {
                    lengths.push(count);
                    count = 0;
                }
            }
        }

        // 마지막이 1로 끝나는 경우
        if (count > 0) {
            lengths.push(count);
        }

        // 배열을 문자열 키로 변환해서 해시맵에 저장
        const key = JSON.stringify(lengths); // '[2,1,3]' 형태
        const index = i + 1; // 1부터 시작

        if (!hashMap[key]) {
            hashMap[key] = [];
        }
        hashMap[key].push(index);
    }

    // Object.values + sort + reduce 사용
    return Object.values(hashMap)
           .sort((a, b) => a.length - b.length)
           .reduce((acc, group) => {
               acc.push(group.join(', '));
               return acc;
           }, []);
}

