function solution(s) {
    const stack = [];
    let currentStr = '';

    for (let char of s) {
        if (char === '[') {
            stack.push(currentStr);
            currentStr = '';
        } else if (char === ']') {
            const prevStr = stack.pop();
            currentStr = prevStr + currentStr.repeat(2);
        } else {
            currentStr += char;
        }
    }

    return currentStr;
}

